// Generate the frozen-F family overrides used only by cut-free Lean projects.
// The current complete library remains generated by scripts/gen-lean-library.ts.
import {createHash} from 'node:crypto'
import {readFileSync, renameSync, writeFileSync} from 'node:fs'
import {join} from 'node:path'

const files = [
  ['CountMachine.lean', 'a7c09c8021b94d3c630b195aa9432d25cb4cb0876d68d46d3cf11e889c9fe1df'],
  ['QAlpha.lean', '3c362e366b8aad32de802feac45e5ab86d0893cefb9b6e0fc9c2e85ef1bf3a4b'],
] as const
const entries = files.map(([file, hash]) => {
  const source = readFileSync(join(import.meta.dir, 'compat/count-family-F', file), 'utf8')
  if (createHash('sha256').update(source).digest('hex') !== hash) throw new Error(`frozen F compatibility source changed: ${file}`)
  return `  ${JSON.stringify(file)}: ${JSON.stringify(source)},`
})
const text = `// Generated by lean-kernel/gen-legacy-family-library.ts from frozen F 41ffd98b: do not edit.\nexport const legacyFamilyLibrary: Readonly<Record<string, string>> = {\n${entries.join('\n')}\n}\n`
const out = join(import.meta.dir, 'legacy-family-library.ts')
if (process.argv.includes('--check')) {
  if (readFileSync(out, 'utf8') !== text) throw new Error('legacy-family-library.ts is out of date')
  console.log('legacy-family-library.ts matches frozen F')
} else {
  writeFileSync(`${out}.tmp`, text)
  renameSync(`${out}.tmp`, out)
}
